  const act=aS/8, inh=iS/8, cor=cS/8;
  const bg = (Math.sin(fx*0.035+fy*0.022+t*0.9)+Math.sin(fx*0.028-fy*0.038+t*1.2))/2
    + Math.sin((fx+fy)*0.11+t*2.8)*0.2 + Math.sin((fx-fy)*0.095-t*2.2)*0.2
